fn contains(list: &Vec<i32>, element: i32) -> bool {
    // Check if the element exists in the list
    for &item in list {
        if item == element {
            return true;
        }
    }
    false
}

fn has_common_element(list1: &Vec<i32>, list2: &Vec<i32>) -> bool {
    // If either list is empty, there can't be a common element
    if list1.is_empty() || list2.is_empty() {
        return false;
    }
    
    // Check each element in list1 to see if it exists in list2
    for &item in list1 {
        if contains(list2, item) {
            return true;
        }
    }
    
    false
}